// Two SDKs generated by wabi-wit-gen in ONE JVM: gematik:pki and gematik:zero.
// Each brings its own runtime (com.gematik.pki.runtime, com.gematik.zero.runtime)
// and its own JNI shim (libgematik_pki_jni, libgematik_zero_jni), so both cores
// can be loaded side by side, through Panama and through JNI. Before the
// runtime was generated per package, both SDKs shipped com.wabi.client.runtime
// and the same libwabi_jni: one jar shadowed the other.
import java.nio.file.Path;

public final class TwoSdks {
    public static void main(String[] args) {
        Path pki = Path.of(args[0]);
        Path zero = Path.of(args[1]);
        int failures = 0;
        for (String binding : new String[] {"panama", "jni"}) {
            var a = com.gematik.pki.runtime.NativeBackend.load(pki, binding);
            var b = com.gematik.zero.runtime.NativeBackend.load(zero, binding);
            String da = a.description(), db = b.description();
            boolean ok = da.contains("gematik:pki") && db.contains("gematik:zero")
                    && com.gematik.pki.runtime.NativeBackend.class != (Class<?>) com.gematik.zero.runtime.NativeBackend.class;
            System.out.println((ok ? "ok    " : "FAIL  ") + binding + ": " + da + " | " + db);
            if (!ok) failures++;
        }
        if (failures > 0) System.exit(1);
    }
}
